    type_from_string,
)

_FUNC_HEADER = re.compile(
    r"^func\.func\s+@(?P<name>[\w.$]+)\s*\((?P<args>[^)]*)\)"
    r"\s*(?:->\s*(?P<ret>[^\s{]+))?\s*\{$")

_HW_MODULE_HEADER = re.compile(
    r"^hw\.module\s+@(?P<name>[\w.$]+)\s*\((?P<ports>[^)]*)\)\s*\{$")

_BLOCK_LABEL = re.compile(r"^\^(?P<label>[\w.$]+):$")

_RESULTS_PREFIX = re.compile(
    r"^(?P<results>%[\w.$]+(?:\s*,\s*%[\w.$]+)*)\s*=\s*(?P<rest>.*)$")

_TOKEN = re.compile(
    r"->|%[\w.$]+|\^[\w.$]+|@[\w.$]+|![\w.$]+|[A-Za-z_][\w.$]*|-?\d+"
    r"|[{}():,=]")

_PORT = re.compile(r"^(?P<dir>in|out)\s+%?(?P<name>[\w.$]+)\s*:\s*(?P<type>.+)$")

_ARG = re.compile(r"^(?P<name>%[\w.$]+)\s*:\s*(?P<type>.+)$")


def parse(source, context=None):
    """Parse MLIR text and return a ``Module``."""
    lines = []
    for raw in source.split("\n"):
        line = raw.split("//", 1)[0].strip()
        if line:
            lines.append(line)
    parser = _Parser(lines, context)
    return parser.parse_module()


class _Parser:
    def __init__(self, lines, context):
        self.lines = lines
        self.pos = 0
        self.module = Module(context)
        self.symbols = {}      # SSA name (with '%') -> Value
        self.value_fixups = []  # (op, [operand names])
        self.block_stack = []   # per function-like op: (op, label_map, succ fixups)

    # -- helpers -------------------------------------------------------------

    def peek(self):
        return self.lines[self.pos] if self.pos < len(self.lines) else None

    def next(self):
        line = self.lines[self.pos]
        self.pos += 1
        return line

    def error(self, msg):
        raise ValueError(f"parse error at line {self.pos + 1}: {msg}: "
                         f"{self.lines[self.pos]!r}" if self.pos < len(self.lines)
                         else f"parse error at end of input: {msg}")

    # -- top level -----------------------------------------------------------

    def parse_module(self):
        if self.next() != "module {":
            self.error("expected 'module {'")
        body = self.module.body
        while True:
            line = self.peek()
            if line is None:
                self.error("unterminated module")
            if line == "}":
                self.next()
                break
            self.parse_op_line(line, body)
            self.pos += 1
        self.resolve_values()
        return self.module

    def resolve_values(self):
        for op, names in self.value_fixups:
            for name in names:
                value = self.symbols.get(name)
                if value is None:
                    raise ValueError(f"undefined SSA value {name!r} "
                                     f"used by op {op.name!r}")
                op.add_operand(value)

    # -- function-like ops ---------------------------------------------------

    def parse_op_line(self, line, block):
        m = _FUNC_HEADER.match(line)
        if m:
            self.parse_func(m, block)
            return
        m = _HW_MODULE_HEADER.match(line)
        if m:
            self.parse_hw_module(m, block)
            return
        op = self.parse_generic_op(line)
        block.add_op(op)

    def parse_func(self, m, parent_block):
        args = []
        arg_text = m.group("args").strip()
        if arg_text:
            for piece in arg_text.split(","):
                am = _ARG.match(piece.strip())
                if not am:
                    raise ValueError(f"bad func argument: {piece!r}")
                args.append((am.group("name"), am.group("type").strip()))
        attributes = {
            "sym_name": m.group("name"),
            "args": args,
        }
        if m.group("ret"):
            attributes["result_type"] = m.group("ret")
        op = Operation("func.func", attributes=attributes)
        parent_block.add_op(op)
        self.parse_body(op, entry_args=args)

    def parse_hw_module(self, m, parent_block):
        ports = []
        port_text = m.group("ports").strip()
        if port_text:
            for piece in port_text.split(","):
                pm = _PORT.match(piece.strip())
                if not pm:
                    raise ValueError(f"bad hw.module port: {piece!r}")
                ports.append({
                    "dir": pm.group("dir"),
                    "name": pm.group("name"),
                    "type": pm.group("type").strip(),
                })
        op = Operation("hw.module", attributes={
            "sym_name": m.group("name"),
            "ports": ports,
        })
        parent_block.add_op(op)
        entry_args = [("%" + p["name"], p["type"]) for p in ports
                      if p["dir"] == "in"]
        self.parse_body(op, entry_args=entry_args)

    def parse_body(self, op, entry_args):
        """Parse ``^label:`` blocks and op lines until the closing brace."""
        region = op.add_region(Region())
        label_map = {}
        succ_fixups = []  # (op, [label names])
        entry = region.add_block()
        for name, type_text in entry_args:
            arg = entry.add_argument(type_from_string(type_text), name)
            self.symbols[name] = arg
        current = entry
        while True:
            line = self.peek()
            if line is None:
                raise ValueError(f"unterminated body of {op.name!r}")
            if line == "}":
                self.next()
                break
            self.next()
            lm = _BLOCK_LABEL.match(line)
            if lm:
                block = region.add_block()
                block.name = lm.group("label")
                label_map[block.name] = block
                current = block
            else:
                parsed = self.parse_generic_op(line)
                current.add_op(parsed)
                if parsed._successor_labels:
                    succ_fixups.append(parsed)
        for parsed in succ_fixups:
            for label in parsed._successor_labels:
                target = label_map.get(label)
                if target is None:
                    raise ValueError(f"undefined block label ^{label!r} "
                                     f"used by op {parsed.name!r}")
                parsed.successors.append(target)
            del parsed._successor_labels

    # -- generic ops ----------------------------------------------------------

    def parse_generic_op(self, line):
        result_names = []
        m = _RESULTS_PREFIX.match(line)
        if m:
            result_names = [r.strip() for r in m.group("results").split(",")]
            rest = m.group("rest")
        else:
            rest = line
        tokens = _TOKEN.findall(rest)
        if not tokens:
            raise ValueError(f"cannot parse op line: {line!r}")
        name = tokens[0]

        operand_names = []
        successor_labels = []
        attributes = {}
        keywords = []
        types = []
        i = 1
        while i < len(tokens):
            tok = tokens[i]
            if tok == ":":
                types = [t for t in tokens[i + 1:]
                         if t not in (",", "(", ")") and t != "->"]
                break
            if tok.startswith("%"):
                operand_names.append(tok)
            elif tok.startswith("^"):
                successor_labels.append(tok[1:])
            elif tok.startswith("-" ) or tok.isdigit():
                attributes["value"] = int(tok)
            elif tok == "reset":
                attributes["reset"] = True
            elif name in ("arith.cmpi", "comb.icmp") and "predicate" not in attributes:
                attributes["predicate"] = tok
            elif tok != ",":
                keywords.append(tok)
            i += 1
        if keywords:
            attributes["keywords"] = keywords
        if types:
            attributes["types"] = types

        result_types = []
        if result_names and types:
            result_types = [type_from_string(types[0])
                            for _ in result_names]
        op = Operation(name, result_types=result_types,
                       attributes=attributes)
        for result, result_name in zip(op.results, result_names):
            result.name = result_name
            self.symbols[result_name] = result
        op._successor_labels = successor_labels
        if operand_names:
            self.value_fixups.append((op, operand_names))
        return op

