"""Rewrite pattern machinery.

``RewritePattern`` subclasses implement ``match_and_rewrite``; a
``PatternRewriter`` performs the actual IR mutations (op replacement,
erasure). ``apply_patterns_greedily`` walks a root op and applies the
patterns until a fixpoint is reached.
"""

from .ir import Operation


class PatternRewriter:
    """Mutates the IR on behalf of patterns and tracks whether it did."""

    def __init__(self):
        self.changed = False

    def insert_op_before(self, ref_op, new_op):
        if ref_op.parent is None:
            raise ValueError("reference op is not attached to a block")
        ref_op.parent.insert_op_before(ref_op, new_op)
        self.changed = True
        return new_op

    def replace_op(self, op, new_op):
        """Insert ``new_op`` before ``op``, forward result uses, erase ``op``."""
        self.insert_op_before(op, new_op)
        op.replace_all_uses_with(new_op)
        op.erase()

    def erase_op(self, op):
        op.erase()
        self.changed = True


class RewritePattern:
    """Base class: return True (and mutate via the rewriter) on a match."""

    def match_and_rewrite(self, op, rewriter):
        raise NotImplementedError


def apply_patterns_greedily(root, patterns, max_iterations=1000):
    """Apply ``patterns`` over ``root`` (inclusive) until fixpoint.

    Returns True if any pattern fired.
    """
    rewriter = PatternRewriter()
    any_change = False
    for _ in range(max_iterations):
        rewriter.changed = False
        ops = []
        root.walk(ops.append)
        for op in ops:
            if op.parent is None and op is not root:
                continue  # erased earlier in this iteration
            for pattern in patterns:
                if pattern.match_and_rewrite(op, rewriter):
                    break
        if not rewriter.changed:
            return any_change
        any_change = True
    raise RuntimeError("greedy pattern application did not converge")

