"""Kernel-level IR with a latency model.

A :class:`KernelOp` is an ordered list of primitive operations, each with a
type, a list of operand value names and a result value name.  The
:class:`LatencyModel` assigns a per-operation latency; the kernel's critical
path latency is modeled as the sum of the latencies of all added operations
(a sequential schedule estimate).
"""


class LatencyModel:
    """Default per-operation latencies (in cycles)."""

    DEFAULT_LATENCIES = {
        "add": 1,
        "sub": 1,
        "mul": 3,
        "div": 10,
        "load": 2,
        "store": 1,
        "cmp": 1,
        "mux": 0,
        "shift": 1,
        "and": 1,
        "or": 1,
        "xor": 1,
    }

    def __init__(self, overrides=None):
        self._latencies = dict(self.DEFAULT_LATENCIES)
        if overrides:
            self._latencies.update(overrides)

    def get_latency(self, op_type):
        """Latency of ``op_type``; unknown operations default to 1."""
        return self._latencies.get(op_type, 1)


class KernelOp:
    """An ordered collection of primitive operations forming a kernel."""

    def __init__(self, name, latency_model=None):
        self.name = name
        self.latency_model = latency_model or LatencyModel()
        # Each record: {"name", "op_type", "operands", "result"}.
        self.operations = []

    def add_operation(self, name, op_type, operands, result):
        """Append an operation to the kernel."""
        self.operations.append({
            "name": name,
            "op_type": op_type,
            "operands": list(operands),
            "result": result,
        })
        return self.operations[-1]

    def total_operations(self):
        """Number of operations added to the kernel."""
        return len(self.operations)

    def critical_path_latency(self):
        """Sum of the latencies of all added operations (0 if none)."""
        return sum(self.latency_model.get_latency(op["op_type"])
                   for op in self.operations)

    def estimated_cycles(self):
        """Estimated cycle count under a sequential schedule."""
        return self.critical_path_latency()

    def __repr__(self):
        return f"KernelOp({self.name!r}, ops={self.total_operations()})"

