"""Symbol and type analysis.

:class:`SymbolTable` resolves value names to their defining operations,
either across a :class:`~k_circt.kernel_ir.KernelOp` or across a parsed
MLIR-like op list (operations whose results/operands are ``Value`` objects
with ``name`` attributes, as in ``src/mlir/ir.py``).  It detects undefined
and multiply-defined symbols.

:class:`TypeResolver` maps symbolic types to concrete MLIR-style integer
types (``"i32"`` etc.) and answers signedness/width queries.
"""

import re


class SymbolTable:
    """Maps value names to the operation that defines them."""

    def __init__(self):
        self._definitions = {}   # name -> defining op (first definition)
        self._definition_ops = {}  # name -> list of all defining ops
        self._uses = {}          # name -> list of using ops

    # -- construction -------------------------------------------------------

    def define(self, name, op):
        self._definition_ops.setdefault(name, []).append(op)
        if name not in self._definitions:
            self._definitions[name] = op

    def use(self, name, op):
        self._uses.setdefault(name, []).append(op)

    @classmethod
    def from_kernel(cls, kernel):
        """Build a table from a KernelOp (records with operands/result)."""
        table = cls()
        for op in kernel.operations:
            table.define(op["result"], op)
        for op in kernel.operations:
            for operand in op["operands"]:
                table.use(operand, op)
        return table

    @classmethod
    def from_ops(cls, ops):
        """Build a table from MLIR-like ops with .results/.operands Values.

        Block arguments (values whose owner is not an operation) can be
        passed in via ``externals`` to mark them as defined.
        """
        table = cls()
        for op in ops:
            for result in getattr(op, "results", []):
                table.define(result.name, op)
        for op in ops:
            for operand in getattr(op, "operands", []):
                table.use(operand.name, op)
        return table

    # -- queries ------------------------------------------------------------

    def lookup(self, name):
        """Return the defining op for ``name``, or None if undefined."""
        return self._definitions.get(name)

    def is_defined(self, name):
        return name in self._definitions

    def defined_names(self):
        return list(self._definitions)

    def undefined_symbols(self):
        """Used names that have no defining operation (sorted)."""
        return sorted(n for n in self._uses if n not in self._definitions)

    def multiply_defined(self):
        """Names defined by more than one operation (sorted)."""
        return sorted(n for n, defs in self._definition_ops.items()
                      if len(defs) > 1)

    def users_of(self, name):
        return list(self._uses.get(name, []))


class TypeResolver:
    """Resolves symbolic types to MLIR-style integer types."""

    DEFAULT_TYPE = "i32"

    _SYMBOLIC = {
        "bool": "i1",
        "bit": "i1",
        "byte": "i8",
        "char": "i8",
        "short": "i16",
        "int": "i32",
        "long": "i64",
        "index": "i32",
        "size_t": "i64",
    }

    _INT_RE = re.compile(r"^([sui]?i)(\d+)$")

    def __init__(self, overrides=None):
        self._symbolic = dict(self._SYMBOLIC)
        if overrides:
            self._symbolic.update(overrides)

    def resolve(self, symbolic_type):
        """Map a symbolic type to a concrete MLIR integer type string.

        Already-concrete types (``i8``, ``si32``, ``ui64``) pass through;
        known symbolic names map per the table; anything else falls back to
        the default (``i32``).
        """
        text = str(symbolic_type).strip()
        if self._INT_RE.match(text):
            return text
        return self._symbolic.get(text, self.DEFAULT_TYPE)

    def width(self, type_str):
        """Bit width of a concrete (or symbolic) integer type."""
        resolved = self.resolve(type_str)
        match = self._INT_RE.match(resolved)
        if not match:
            return int(self.DEFAULT_TYPE[1:])
        return int(match.group(2))

    def is_signed(self, type_str):
        """Signedness: ``si*`` signed, ``ui*`` unsigned; plain ``i*`` and
        symbolic integer types are treated as signed two's complement."""
        resolved = self.resolve(type_str)
        if resolved.startswith("ui"):
            return False
        return True

