"""The Kimulator: a K-inspired executable trace engine for circuits.

Evaluation proceeds by explicit, named semantic rules in the style of the
K framework: each rule is a function that takes the current configuration
(a cell-like state: signal store, register file, cycle counter) and rewrites
it.  The :class:`Kimulator` loads a small op-list program, applies the rules
step by step, and records a trace of per-cycle state snapshots together with
the names of the rules that fired.

Program format — a list of instruction tuples::

    ("const", dest, value)        # dest = value
    ("add"|"sub"|"mul", dest, a, b)
    ("and"|"or"|"xor", dest, a, b)
    ("mux", dest, cond, a, b)     # dest = a if cond else b
    ("reg", name, src)            # register name <- src at the cycle tick

Operands ``a``/``b``/``cond``/``src`` are either integer literals or value
names, resolved first against the signal store, then the register file.
"""

from dataclasses import dataclass, field


# ---------------------------------------------------------------------------
# Configuration (the K "configuration" of cells)
# ---------------------------------------------------------------------------

@dataclass
class Configuration:
    """Cell-like machine state: signal store, register file, cycle counter."""

    signals: dict = field(default_factory=dict)
    registers: dict = field(default_factory=dict)
    cycle: int = 0

    def snapshot(self):
        return {
            "signals": dict(self.signals),
            "registers": dict(self.registers),
            "cycle": self.cycle,
        }


def _read(config, operand):
    """Resolve an operand: literal int, signal, then register."""
    if isinstance(operand, int):
        return operand
    if operand in config.signals:
        return config.signals[operand]
    if operand in config.registers:
        return config.registers[operand]
    raise KeyError(f"undefined operand {operand!r} at cycle {config.cycle}")


# ---------------------------------------------------------------------------
# Semantic rules (each takes the configuration, rewrites it, returns a value)
# ---------------------------------------------------------------------------

def rule_const(config, dest, value):
    config.signals[dest] = int(value)
    return config.signals[dest]


def rule_add(config, dest, a, b):
    config.signals[dest] = _read(config, a) + _read(config, b)
    return config.signals[dest]


def rule_sub(config, dest, a, b):
    config.signals[dest] = _read(config, a) - _read(config, b)
    return config.signals[dest]


def rule_mul(config, dest, a, b):
    config.signals[dest] = _read(config, a) * _read(config, b)
    return config.signals[dest]


def rule_and(config, dest, a, b):
    config.signals[dest] = _read(config, a) & _read(config, b)
    return config.signals[dest]


def rule_or(config, dest, a, b):
    config.signals[dest] = _read(config, a) | _read(config, b)
    return config.signals[dest]


def rule_xor(config, dest, a, b):
    config.signals[dest] = _read(config, a) ^ _read(config, b)
    return config.signals[dest]


def rule_mux(config, dest, cond, a, b):
    config.signals[dest] = _read(config, a) if _read(config, cond) \
        else _read(config, b)
    return config.signals[dest]


def rule_reg_tick(config, pending):
    """Clock tick: apply pending register updates and advance the cycle."""
    for name, value in pending.items():
        config.registers[name] = value
    config.cycle += 1
    return config


# ---------------------------------------------------------------------------
# Kimulator
# ---------------------------------------------------------------------------

class Kimulator:
    """Loads a program, applies semantic rules step by step, records a trace."""

    RULES = {
        "const": rule_const,
        "add": rule_add,
        "sub": rule_sub,
        "mul": rule_mul,
        "and": rule_and,
        "or": rule_or,
        "xor": rule_xor,
        "mux": rule_mux,
    }

    def __init__(self, program=None, registers=None):
        self.config = Configuration(registers=dict(registers or {}))
        self.program = []
        self.trace = []
        if program:
            self.load(program)

    def load(self, program):
        """Load an op-list program (list of instruction tuples)."""
        self.program = [tuple(instr) for instr in program]

    def load_mlir_module(self, module):
        """Best-effort import of a parsed ``src/mlir`` module.

        Walks the ops of the first ``hw.module`` (or the module body itself)
        and translates hw/comb/seq ops into the op-list program format.
        """
        ops = []
        for top in getattr(module, "ops", []):
            if top.name == "hw.module" and top.regions:
                ops = list(top.regions[0].blocks[0].ops)
                break
        else:
            ops = [op for op in getattr(module, "ops", [])
                   if op.name != "builtin.module"]

        program = []
        for op in ops:
            names = [v.name for v in op.operands]
            result = op.results[0].name if op.results else None
            if op.name == "hw.constant":
                program.append(("const", result, op.attributes["value"]))
            elif op.name in ("comb.add", "comb.sub", "comb.mul",
                             "comb.and", "comb.or", "comb.xor"):
                program.append((op.name.split(".")[1], result, *names[:2]))
            elif op.name == "comb.mux":
                program.append(("mux", result, *names[:3]))
            elif op.name == "seq.compreg":
                # operands: [next, clk, reset?, reset_value?]
                program.append(("reg", result, names[0]))
            # hw.output and anything else: ignored.
        self.load(program)

    def step(self):
        """Execute one cycle: fire each op's rule, then the register tick."""
        fired_rules = []
        pending = {}
        for instr in self.program:
            opcode, args = instr[0], instr[1:]
            if opcode == "reg":
                name, src = args
                pending[name] = _read(self.config, src)
                fired_rules.append("rule_reg")
                continue
            rule = self.RULES.get(opcode)
            if rule is None:
                raise ValueError(f"no semantic rule for op {opcode!r}")
            rule(self.config, *args)
            fired_rules.append(f"rule_{opcode}")
        rule_reg_tick(self.config, pending)
        fired_rules.append("rule_reg_tick")
        self.trace.append({
            "cycle": self.config.cycle,
            "rules": fired_rules,
            "state": self.config.snapshot(),
        })
        return self.config

    def run(self, num_cycles):
        """Run ``num_cycles`` steps; returns the final configuration."""
        for _ in range(num_cycles):
            self.step()
        return self.config

    @property
    def trace_length(self):
        return len(self.trace)

    @property
    def final_state(self):
        return self.config.snapshot()

    def fired_rule_names(self):
        """Flat list of rule names fired across the whole trace."""
        return [name for entry in self.trace for name in entry["rules"]]

